 s=ls[n-1]; runs=[]; i=lo
 while i<min(len(s),hi):
  if s[i].isspace(): i+=1; continue
  j=i+1
  while j<min(len(s),hi) and not s[j].isspace(): j+=1
  runs.append([i+1,j,s[i:j]]); i=j
 merged=[]
